//! The placeholder strategic icons (WP3.6): 64 x 64 PNGs, a white symbol on
//! transparent with the inner sign black, drawn from signed distance
//! functions with nothing but `+ - * /` and `sqrt` (IEEE exact, so the output is
//! the same on every machine). Replace them with artist icons following
//! `docs/rules/icons.md`; until then these are generated by the project (no
//! third-party material).
//!
//! # The format (the engine's side is `sf_render::icon_atlas`)
//! * The image is the *art box* of the icon: 64 x 64 texels, drawn at 1.2 times the
//!   icon size in pixels (so 14 px icons use a 16.8 px box).
//! * Alpha is the silhouette of the base shape (square, circle, triangle or
//!   half-circle). Inside it the colour is white (where the owner's colour
//!   shows) or black (the sign). A sign may also be cut out of the alpha
//!   instead; the engine reads both.
//! * Coordinates below are texels from the centre of the image, y up.

use std::collections::BTreeMap;
use std::f64::consts::FRAC_1_SQRT_2;

/// Side of an icon image in texels.
pub const SIDE: usize = 64;

/// Half the side of the square (and the radius of the circle) in texels: the
/// 14 px of the nominal icon size inside the 16.8 px art box (`64 / 1.2 / 2`).
pub const H: f64 = SIDE as f64 / 2.4;
/// Half the width of the triangle: a little narrower than the image, so its
/// antialiased corners are not cut off (about 1.2 times the square's width, as
/// the shader's old triangle was).
pub const TRI_HALF: f64 = 31.0;
/// Radius of the vessel's half-circle.
pub const VESSEL_R: f64 = 31.5;

/// A signed distance function: negative inside, in texels.
type Sdf = Box<dyn Fn(f64, f64) -> f64>;

// ---- primitives ---------------------------------------------------------

fn length(x: f64, y: f64) -> f64 {
    (x * x + y * y).sqrt()
}

fn circle(cx: f64, cy: f64, r: f64) -> Sdf {
    Box::new(move |x, y| length(x - cx, y - cy) - r)
}

/// An axis-aligned box.
fn rect(cx: f64, cy: f64, hx: f64, hy: f64) -> Sdf {
    obox(cx, cy, hx, hy, 1.0, 0.0)
}

/// A box with half sizes `hx` along the unit direction `(ux, uy)` and `hy`
/// across it.
fn obox(cx: f64, cy: f64, hx: f64, hy: f64, ux: f64, uy: f64) -> Sdf {
    Box::new(move |x, y| {
        let (dx, dy) = (x - cx, y - cy);
        let (a, b) = (dx * ux + dy * uy, -dx * uy + dy * ux);
        let (qx, qy) = (a.abs() - hx, b.abs() - hy);
        length(qx.max(0.0), qy.max(0.0)) + qx.max(qy).min(0.0)
    })
}

/// A bar with flat ends from `(x0, y0)` to `(x1, y1)`, `half` thick on each side.
fn bar(x0: f64, y0: f64, x1: f64, y1: f64, half: f64) -> Sdf {
    let (dx, dy) = (x1 - x0, y1 - y0);
    let len = length(dx, dy);
    obox(
        (x0 + x1) / 2.0,
        (y0 + y1) / 2.0,
        len / 2.0,
        half,
        dx / len,
        dy / len,
    )
}

fn ring(cx: f64, cy: f64, outer: f64, inner: f64) -> Sdf {
    Box::new(move |x, y| {
        let d = length(x - cx, y - cy);
        (d - outer).max(inner - d)
    })
}

/// The points whose `nx * x + ny * y` is at most `c`; `(nx, ny)` is a unit vector.
fn half_plane(nx: f64, ny: f64, c: f64) -> Sdf {
    Box::new(move |x, y| nx * x + ny * y - c)
}

/// A simple polygon.
fn polygon(points: &[(f64, f64)]) -> Sdf {
    let pts = points.to_vec();
    Box::new(move |px, py| {
        let n = pts.len();
        let mut d = (px - pts[0].0) * (px - pts[0].0) + (py - pts[0].1) * (py - pts[0].1);
        let mut s = 1.0;
        let mut j = n - 1;
        for i in 0..n {
            let (ex, ey) = (pts[j].0 - pts[i].0, pts[j].1 - pts[i].1);
            let (wx, wy) = (px - pts[i].0, py - pts[i].1);
            let t = ((wx * ex + wy * ey) / (ex * ex + ey * ey)).clamp(0.0, 1.0);
            let (bx, by) = (wx - ex * t, wy - ey * t);
            d = d.min(bx * bx + by * by);
            let c = [py >= pts[i].1, py < pts[j].1, ex * wy > ey * wx];
            if c.iter().all(|&v| v) || c.iter().all(|&v| !v) {
                s = -s;
            }
            j = i;
        }
        s * d.sqrt()
    })
}

fn union(parts: Vec<Sdf>) -> Sdf {
    Box::new(move |x, y| parts.iter().map(|p| p(x, y)).fold(f64::MAX, f64::min))
}

fn inter(a: Sdf, b: Sdf) -> Sdf {
    Box::new(move |x, y| a(x, y).max(b(x, y)))
}

fn sub(a: Sdf, b: Sdf) -> Sdf {
    Box::new(move |x, y| a(x, y).max(-b(x, y)))
}

/// `f` drawn `scale` times as big around the origin, then moved by `(dx, dy)`.
fn place(f: Sdf, scale: f64, dx: f64, dy: f64) -> Sdf {
    Box::new(move |x, y| f((x - dx) / scale, (y - dy) / scale) * scale)
}

// ---- the base shapes ------------------------------------------------------

/// The four silhouettes (PLAN.md section 2.2: triangle = vehicle, square =
/// building, circle = infantry, half-circle = vessel).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Base {
    Square,
    Circle,
    Triangle,
    HalfCircle,
}

impl Base {
    pub const ALL: [Base; 4] = [Base::Square, Base::Circle, Base::Triangle, Base::HalfCircle];

    /// The file stem of the plain shape.
    pub fn name(self) -> &'static str {
        match self {
            Base::Square => "base_square",
            Base::Circle => "base_circle",
            Base::Triangle => "base_triangle",
            Base::HalfCircle => "base_halfcircle",
        }
    }

    fn silhouette(self) -> Sdf {
        match self {
            Base::Square => rect(0.0, 0.0, H, H),
            Base::Circle => circle(0.0, 0.0, H),
            Base::Triangle => {
                let h = TRI_HALF * 3.0_f64.sqrt();
                polygon(&[(0.0, h / 2.0), (-TRI_HALF, -h / 2.0), (TRI_HALF, -h / 2.0)])
            }
            // A bowl: flat deck on top, round hull below, the box centred.
            Base::HalfCircle => inter(
                circle(0.0, VESSEL_R / 2.0, VESSEL_R),
                half_plane(0.0, 1.0, VESSEL_R / 2.0),
            ),
        }
    }
}

// ---- the signs ------------------------------------------------------------

fn wrench() -> Sdf {
    let s = FRAC_1_SQRT_2;
    let head = sub(
        sub(circle(7.0, 7.0, 10.0), circle(7.0, 7.0, 4.4)),
        obox(13.0, 13.0, 7.0, 3.6, s, s),
    );
    union(vec![bar(-13.0, -13.0, 3.0, 3.0, 4.6), head])
}

/// A shovel, blade down to the right, handle up to the left (the engineer's tool).
fn shovel() -> Sdf {
    let s = FRAC_1_SQRT_2;
    union(vec![
        bar(-14.0, 14.0, 2.0, -2.0, 3.6),
        obox(8.0, -8.0, 9.0, 8.0, s, -s),
    ])
}

fn bolt() -> Sdf {
    polygon(&[
        (7.0, 19.0),
        (-12.0, -2.0),
        (-1.5, -2.0),
        (-7.0, -19.0),
        (12.0, 4.0),
        (2.5, 4.0),
    ])
}

fn wave() -> Sdf {
    union(vec![
        inter(ring(-9.5, 0.0, 11.0, 3.0), half_plane(0.0, -1.0, 0.0)),
        inter(ring(9.5, 0.0, 11.0, 3.0), half_plane(0.0, 1.0, 0.0)),
    ])
}

fn sight(cx: f64, cy: f64, outer: f64, inner: f64) -> Sdf {
    ring(cx, cy, outer, inner)
}

fn gear() -> Sdf {
    let s = FRAC_1_SQRT_2;
    let spokes = union(vec![
        bar(-17.0, 0.0, 17.0, 0.0, 4.2),
        bar(0.0, -17.0, 0.0, 17.0, 4.2),
        bar(-17.0 * s, -17.0 * s, 17.0 * s, 17.0 * s, 4.2),
        bar(-17.0 * s, 17.0 * s, 17.0 * s, -17.0 * s, 4.2),
    ]);
    sub(
        union(vec![spokes, circle(0.0, 0.0, 12.0)]),
        circle(0.0, 0.0, 4.2),
    )
}

fn hammer() -> Sdf {
    let s = FRAC_1_SQRT_2;
    union(vec![
        bar(-13.0, -13.0, 7.0, 7.0, 3.2),
        obox(8.5, 8.5, 11.0, 5.0, -s, s),
    ])
}

fn radar() -> Sdf {
    // Two quarter arcs opening towards the upper right and the dot they
    // spread from, in the lower left corner.
    let quadrant = |outer: f64, inner: f64| {
        inter(
            inter(
                ring(-10.0, -10.0, outer, inner),
                half_plane(-1.0, 0.0, 10.0),
            ),
            half_plane(0.0, -1.0, 10.0),
        )
    };
    union(vec![quadrant(23.0, 12.0), circle(-10.0, -10.0, 6.4)])
}

fn eye() -> Sdf {
    let almond = |a: f64, b: f64| {
        let r = (a * a + b * b) / (2.0 * b);
        let c = r - b;
        inter(circle(0.0, -c, r), circle(0.0, c, r))
    };
    union(vec![
        sub(almond(20.0, 11.0), almond(13.0, 4.5)),
        circle(0.0, 0.0, 5.6),
    ])
}

fn drop_sign() -> Sdf {
    union(vec![
        circle(0.0, -7.0, 11.0),
        polygon(&[(0.0, 19.0), (-10.2, -3.5), (10.2, -3.5)]),
    ])
}

/// The sign of an icon: `None` is a plain base shape.
fn sign(name: &str) -> Option<Sdf> {
    let s = FRAC_1_SQRT_2;
    Some(match name {
        // ---- infantry (circle) ----
        "rifleman" => circle(0.0, 0.0, 10.5),
        "rocket_trooper" => bar(-13.0, -13.0, 13.0, 13.0, 5.6),
        "engineer" => shovel(),
        "scout" => eye(),
        "sniper" => union(vec![
            ring(0.0, 0.0, 16.0, 9.5),
            bar(-19.0, 0.0, -5.0, 0.0, 3.2),
            bar(5.0, 0.0, 19.0, 0.0, 3.2),
            bar(0.0, -19.0, 0.0, -5.0, 3.2),
            bar(0.0, 5.0, 0.0, 19.0, 3.2),
        ]),
        "medic" => union(vec![
            bar(-15.0, 8.5, 15.0, 8.5, 4.4),
            bar(-15.0, -8.5, 15.0, -8.5, 4.4),
        ]),
        "demolition_team" => union(vec![
            bar(0.0, -15.0, 0.0, 15.0, 2.9),
            bar(-13.0, -7.5, 13.0, 7.5, 2.9),
            bar(-13.0, 7.5, 13.0, -7.5, 2.9),
        ]),
        "combat_engineer" => union(vec![
            place(shovel(), 0.8, -3.0, -3.0),
            circle(11.0, 11.0, 5.2),
        ]),
        "heavy_gun_team" => union(vec![
            bar(-15.0, 10.0, 15.0, 10.0, 3.5),
            bar(0.0, 10.0, 0.0, -16.0, 3.5),
        ]),
        "technician" => wrench(),
        // ---- vehicles (triangle) ----
        "harvester" => obox(0.0, -8.0, 10.5, 10.5, s, s),
        "light_tank" => rect(0.0, -8.0, 7.0, 13.0),
        "heavy_tank" => union(vec![
            rect(-8.0, -11.0, 3.8, 9.0),
            rect(8.0, -11.0, 3.8, 9.0),
        ]),
        "siege_artillery" => inter(ring(0.0, -19.0, 19.0, 7.5), half_plane(0.0, -1.0, 19.0)),
        "repair_truck" => place(wrench(), 1.0, -1.0, -9.0),
        "light_transport" => rect(0.0, -12.0, 12.0, 6.5),
        "transport_truck" => rect(0.0, -6.0, 19.0, 4.8),
        "amphibious_transport" => place(wave(), 1.0, 0.0, -10.0),
        "supply_truck" => sub(rect(0.0, -12.0, 11.0, 9.5), rect(0.0, -12.0, 5.0, 3.8)),
        // ---- vessels (half-circle) ----
        "gunboat" => rect(0.0, -1.0, 7.0, 12.0),
        "ferry" => rect(0.0, 1.0, 19.0, 4.4),
        // ---- structures (square) ----
        "construction_center" => hammer(),
        "power_plant" => bolt(),
        "refinery" => obox(0.0, 0.0, 12.0, 12.0, s, s),
        "barracks" => circle(0.0, 0.0, 10.5),
        "vehicle_factory" => gear(),
        "radar" => radar(),
        "defence_tower" => sight(0.0, 0.0, 15.0, 5.0),
        "advanced_defences" => union(vec![
            sight(-10.5, 0.0, 11.0, 3.2),
            sight(10.5, 0.0, 11.0, 3.2),
        ]),
        "shipyard" => place(wave(), 1.1, 0.0, 0.0),
        "fortified_bunker" => union(vec![
            sight(0.0, 5.0, 12.0, 7.5),
            rect(0.0, -19.0, 30.0, 6.0),
        ]),
        "automated_gun" => union(vec![sight(0.0, 0.0, 18.5, 9.5), circle(0.0, 0.0, 4.6)]),
        "unmanned_artillery" => union(vec![
            inter(ring(0.0, -8.0, 19.0, 10.0), half_plane(0.0, -1.0, 8.0)),
            circle(0.0, -14.0, 5.6),
        ]),
        // A mast with antenna arms (a Y or psi): the stem and a cup open upwards.
        "relay_transmitter" => union(vec![
            bar(0.0, -19.0, 0.0, 9.0, 3.4),
            inter(ring(0.0, 4.0, 16.0, 9.0), half_plane(0.0, 1.0, 4.0)),
            bar(-12.5, 4.0, -12.5, 17.0, 3.4),
            bar(12.5, 4.0, 12.5, 17.0, 3.4),
        ]),
        "fuel_depot" => drop_sign(),
        // A heavy dark disc with the bolt cut out of it: solid at 14 px.
        "generator" => sub(circle(0.0, 0.0, 18.5), place(bolt(), 0.78, 0.0, 0.0)),
        "archive_building" => union(vec![
            bar(-15.0, 11.0, 15.0, 11.0, 3.0),
            bar(-15.0, 0.0, 15.0, 0.0, 3.0),
            bar(-15.0, -11.0, 15.0, -11.0, 3.0),
        ]),
        other => panic!("no sign for icon {other:?}"),
    })
}

// ---- the set --------------------------------------------------------------

/// One icon of the set: its name, its base shape and whether it carries a sign.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct IconSpec {
    pub name: &'static str,
    pub base: Base,
}

/// Every icon of the set, the four plain base shapes first, then the roles by
/// base shape in the order of the art brief.
pub fn icon_specs() -> Vec<IconSpec> {
    let mut out: Vec<IconSpec> = Base::ALL
        .iter()
        .map(|&base| IconSpec {
            name: base.name(),
            base,
        })
        .collect();
    let groups: [(Base, &[&str]); 4] = [
        (
            Base::Circle,
            &[
                "rifleman",
                "rocket_trooper",
                "engineer",
                "scout",
                "sniper",
                "medic",
                "demolition_team",
                "combat_engineer",
                "heavy_gun_team",
                "technician",
            ],
        ),
        (
            Base::Triangle,
            &[
                "harvester",
                "light_tank",
                "heavy_tank",
                "siege_artillery",
                "repair_truck",
                "light_transport",
                "transport_truck",
                "amphibious_transport",
                "supply_truck",
            ],
        ),
        (Base::HalfCircle, &["gunboat", "ferry"]),
        (
            Base::Square,
            &[
                "construction_center",
                "power_plant",
                "refinery",
                "barracks",
                "vehicle_factory",
                "radar",
                "defence_tower",
                "advanced_defences",
                "shipyard",
                "fortified_bunker",
                "automated_gun",
                "unmanned_artillery",
                "relay_transmitter",
                "fuel_depot",
                "generator",
                "archive_building",
            ],
        ),
    ];
    for (base, names) in groups {
        out.extend(names.iter().map(|&name| IconSpec { name, base }));
    }
    out
}

/// Names that share another icon's picture on purpose: `(name, file stem)`.
/// The decoy has the defence tower's sign so that it fools the enemy; the
/// civilian's sign is empty, which is the plain circle.
pub const ALIASES: &[(&str, &str)] = &[
    ("decoy_emplacement", "defence_tower"),
    ("civilian", "base_circle"),
];

fn coverage(sd: f64) -> f64 {
    (0.5 - sd).clamp(0.0, 1.0)
}

/// The RGBA pixels of an icon, 64 x 64, straight (not premultiplied) alpha.
pub fn render(spec: IconSpec) -> Vec<u8> {
    let silhouette = spec.base.silhouette();
    let mark = if spec.name == spec.base.name() {
        None
    } else {
        sign(spec.name)
    };
    let mut out = Vec::with_capacity(SIDE * SIDE * 4);
    for j in 0..SIDE {
        for i in 0..SIDE {
            let x = i as f64 + 0.5 - SIDE as f64 / 2.0;
            let y = SIDE as f64 / 2.0 - (j as f64 + 0.5);
            let alpha = coverage(silhouette(x, y));
            let sign = mark.as_ref().map_or(0.0, |m| coverage(m(x, y)));
            // The sign is only ever inside the silhouette.
            let grey = (1.0 - sign.min(1.0)) * 255.0;
            let g = grey.round() as u8;
            out.extend_from_slice(&[g, g, g, (alpha * 255.0).round() as u8]);
        }
    }
    out
}

/// A PNG file (8-bit RGBA) of the pixels.
pub fn encode_png(rgba: &[u8]) -> Vec<u8> {
    let mut bytes = Vec::new();
    {
        let mut encoder = png::Encoder::new(&mut bytes, SIDE as u32, SIDE as u32);
        encoder.set_color(png::ColorType::Rgba);
        encoder.set_depth(png::BitDepth::Eight);
        let mut writer = encoder.write_header().expect("PNG header");
        writer.write_image_data(rgba).expect("PNG data");
        writer.finish().expect("PNG end");
    }
    bytes
}

/// The pixels of an 8-bit RGBA PNG.
pub fn decode_png(bytes: &[u8]) -> Result<Vec<u8>, String> {
    let mut reader = png::Decoder::new(std::io::Cursor::new(bytes))
        .read_info()
        .map_err(|e| e.to_string())?;
    let mut buf = vec![0; reader.output_buffer_size().ok_or("PNG too large")?];
    let info = reader.next_frame(&mut buf).map_err(|e| e.to_string())?;
    if (info.width, info.height) != (SIDE as u32, SIDE as u32)
        || info.color_type != png::ColorType::Rgba
        || info.bit_depth != png::BitDepth::Eight
    {
        return Err(format!(
            "expected a {SIDE}x{SIDE} 8-bit RGBA PNG, got {}x{} {:?}",
            info.width, info.height, info.color_type
        ));
    }
    buf.truncate(info.buffer_size());
    Ok(buf)
}

/// The text of `icons.ron`: icon name to file, the aliases last.
pub fn manifest() -> String {
    let mut map: BTreeMap<&str, String> = BTreeMap::new();
    for spec in icon_specs() {
        map.insert(spec.name, format!("{}.png", spec.name));
    }
    for (name, target) in ALIASES {
        map.insert(name, format!("{target}.png"));
    }
    let mut text = String::from(
        "// Icon names to files under assets/icons (WP3.6), written by tools/sf_icon_gen\n\
         // together with the PNGs. Unit definitions name an icon in `icon:`; a name that\n\
         // is not here but has a `<name>.png` next to this file works too. Two names\n\
         // with the same file share one picture (the decoy has the defence tower's).\n\
         // See docs/rules/icons.md.\n\
         (\n    icons: {\n",
    );
    for (name, file) in &map {
        text.push_str(&format!("        \"{name}\": \"{file}\",\n"));
    }
    text.push_str("    },\n)\n");
    text
}

/// Whether two copies of a text file are the same apart from line endings (a
/// Windows checkout may have turned `\n` into `\r\n`).
pub fn same_text(a: &[u8], b: &[u8]) -> bool {
    let strip = |t: &[u8]| {
        t.iter()
            .copied()
            .filter(|&c| c != b'\r')
            .collect::<Vec<_>>()
    };
    strip(a) == strip(b)
}

/// Every file of the set as `(file name, bytes)`: the PNGs and `icons.ron`.
pub fn files() -> Vec<(String, Vec<u8>)> {
    let mut out: Vec<(String, Vec<u8>)> = icon_specs()
        .into_iter()
        .map(|spec| (format!("{}.png", spec.name), encode_png(&render(spec))))
        .collect();
    out.push(("icons.ron".to_string(), manifest().into_bytes()));
    out
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::path::PathBuf;

    fn assets_icons() -> PathBuf {
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../assets/icons")
    }

    #[test]
    fn the_set_has_the_four_bases_and_every_role_of_the_brief() {
        let specs = icon_specs();
        // 4 plain shapes and 37 roles with a sign of their own; the decoy and
        // the civilian share a picture (the aliases), which makes the 39 roles
        // of the art brief.
        assert_eq!(specs.len(), 4 + 37);
        assert_eq!(specs.len() - 4 + ALIASES.len(), 39);
        let mut names: Vec<_> = specs.iter().map(|s| s.name).collect();
        names.sort_unstable();
        names.dedup();
        assert_eq!(names.len(), specs.len(), "no name twice");
        for (alias, target) in ALIASES {
            assert!(names.contains(target), "{alias} points at {target}");
            assert!(!names.contains(alias));
        }
    }

    #[test]
    fn rendering_is_deterministic() {
        for spec in icon_specs() {
            assert_eq!(render(spec), render(spec), "{}", spec.name);
        }
    }

    #[test]
    fn every_icon_is_a_filled_silhouette_with_a_sign_inside_it() {
        for spec in icon_specs() {
            let px = render(spec);
            let opaque = px.chunks(4).filter(|p| p[3] == 255).count();
            assert!(
                opaque > 1000 && opaque < 3500,
                "{}: {opaque} opaque texels",
                spec.name
            );
            // The sign is black, the rest white, only inside the silhouette.
            let dark = px.chunks(4).filter(|p| p[3] > 128 && p[0] < 128).count();
            let plain = spec.name == spec.base.name();
            assert_eq!(dark == 0, plain, "{}: {dark} dark texels", spec.name);
            // Nothing touches the border of the image (the engine adds a
            // margin of its own, but the silhouette must not be cut off).
            for i in 0..SIDE {
                for (x, y) in [(i, 0), (i, SIDE - 1), (0, i), (SIDE - 1, i)] {
                    assert!(
                        px[(y * SIDE + x) * 4 + 3] < 255,
                        "{}: touches border",
                        spec.name
                    );
                }
            }
        }
    }

    #[test]
    fn the_committed_files_are_what_the_generator_writes() {
        let dir = assets_icons();
        for (name, bytes) in files() {
            let on_disk = std::fs::read(dir.join(&name))
                .unwrap_or_else(|e| panic!("{name}: {e}; run `cargo run -p sf_icon_gen`"));
            if name.ends_with(".png") {
                assert_eq!(
                    decode_png(&on_disk).unwrap(),
                    decode_png(&bytes).unwrap(),
                    "{name} is out of date; run `cargo run -p sf_icon_gen`"
                );
            } else {
                assert!(same_text(&on_disk, &bytes), "{name} is out of date");
            }
        }
    }
}
